 90	func (w *responseWriter) Status() int {
 91		return w.status
 92	}
 93	
 94	func (w *responseWriter) Size() int {
 95		return w.size
 96	}
 97	
 98	func (w *responseWriter) Written() bool {
 99		return w.size != noWritten
100	}
