102	// Hijack implements the http.Hijacker interface.
103	func (w *responseWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
104		if w.size < 0 {
105			w.size = 0
106		}
107		return w.ResponseWriter.(http.Hijacker).Hijack()
108	}
